settings.custom_liquid:
{% comment %}
  Footer - חנות השופט (includes the BlackZ signature)
  Setup: Customize → Footer group → Add section → Custom Liquid → paste this.
  Then hide the theme's own Footer section (eye icon) and delete the old BlackZ signature block.
  ✏️ Edit links / texts below.
{% endcomment %}

{%- assign wa_number = '972515310498' -%}
{%- assign ig_handle = 'hanut.hashofet' -%}
{%- assign tt_handle = 'hashofet.il' -%}

<style>
  /* remove the theme's padding/margin around this section (causes the white bar) */
  .shopify-section:has(.ftr), .shopify-section:has(.ftr) > *, .shopify-section:has(.ftr) [class*="padding"] { padding: 0 !important; margin: 0 !important; }
  .footer-group:has(.ftr), #shopify-section-footer:has(.ftr) { margin: 0 !important; padding: 0 !important; }

  .ftr {
    --bg: #111112; --line: rgba(255,255,255,.10); --text: #d9d7d2; --muted: #8f8d88; --gold: #f2b51b; --wa: #25d366;
    direction: rtl; background: var(--bg); color: var(--text); font-family: inherit;
    padding: 56px 0 0; margin: 0;
  }
  .ftr a { color: inherit; text-decoration: none; }
  .ftr a:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; border-radius: 6px; }
  .ftr__wrap { max-width: 1180px; margin: 0 auto; padding: 0 20px; }

  .ftr__top { display: grid; grid-template-columns: 1.4fr 1fr 1fr 1fr; gap: 36px; padding-bottom: 40px; }
  .ftr__brand b { display: block; font-size: 30px; font-weight: 900; color: #fff; letter-spacing: -0.02em; }
  .ftr__brand p { margin: 12px 0 20px; font-size: 15px; line-height: 1.65; color: var(--muted); max-width: 380px; }
  .ftr__wa {
    display: inline-flex; align-items: center; gap: 10px; background: var(--wa); color: #fff !important;
    font-weight: 900; font-size: 15px; padding: 12px 20px; border-radius: 14px; transition: transform .2s ease;
    white-space: nowrap; flex-wrap: nowrap;
  }
  .ftr__phone { display: block; margin-top: 8px; font-size: 14px; color: var(--muted); direction: ltr; unicode-bidi: isolate; text-align: right; }
  .ftr__phone:hover { color: #fff; }
  .ftr__wa:hover { transform: translateY(-2px); }
  .ftr__wa svg { width: 20px; height: 20px; }
  .ftr__soc { display: flex; gap: 10px; margin-top: 16px; }
  .ftr__soc a { width: 42px; height: 42px; border-radius: 12px; border: 1px solid var(--line); display: flex; align-items: center; justify-content: center; transition: background .2s, border-color .2s; }
  .ftr__soc a:hover { background: rgba(255,255,255,.08); border-color: rgba(255,255,255,.25); }
  .ftr__soc svg { width: 19px; height: 19px; fill: #fff; }

  .ftr__col h3 { margin: 6px 0 14px; font-size: 14px; font-weight: 900; color: #fff; }
  .ftr__col ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
  .ftr__col a { font-size: 15px; color: var(--muted); transition: color .2s; }
  .ftr__col a:hover { color: #fff; }
  .ftr__col a.is-hot { color: var(--gold); font-weight: 800; }

  .ftr__pay { border-top: 1px solid var(--line); padding: 22px 0; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
  .ftr__pay-l { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 13px; color: var(--muted); font-weight: 700; }
  .ftr__badge { display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 14px; border-radius: 10px; background: #fff; color: #111 !important; font-size: 13.5px; font-weight: 900; }
  .ftr__badge svg { width: 18px; height: 18px; }
  .ftr__ship { font-size: 13px; color: var(--muted); }
  .ftr__ship b { color: var(--text); }

  .ftr__bottom { border-top: 1px solid var(--line); padding: 16px 0 20px; display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
  .ftr__copy { font-size: 13px; color: var(--muted); }
  .ftr blackz-signature { --bz-mark: #ffffff; }

  @media (max-width: 900px) {
    .ftr { padding-top: 42px; }
    .ftr__top { grid-template-columns: 1fr 1fr; gap: 28px 20px; }
    .ftr__brand { grid-column: 1 / -1; }
    .ftr__pay, .ftr__bottom { flex-direction: column; align-items: flex-start; }
  }
  @media (prefers-reduced-motion: reduce) { .ftr__wa, .ftr__soc a, .ftr__col a { transition: none; } }
</style>

